package local.skyfamily;
import android.database.Cursor;import android.net.Uri;import android.graphics.*;import org.json.*;import java.io.*;import java.util.UUID;import java.util.zip.*;import java.nio.ByteBuffer;import java.nio.charset.*;
final class BookImport {
 static void remove(File file,File cover){if(file!=null)file.delete();if(cover!=null)cover.delete();}
 static void add(RefinedActivity host,Uri uri){String found="Imported book";try(Cursor cursor=host.getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())found=cursor.getString(0);}catch(Exception ignored){}final String name=found==null?"Imported book":found;host.page("Adding to bookshelf");host.text("Detecting and validating "+name+"...");final int stamp=host.revision;host.work(()->{File directory=host.bookDir();long used=0;File[] existing=directory.listFiles();if(existing!=null)for(File item:existing)used+=item.length();if(host.index().length()>=100)throw new IOException("Bookshelf limit reached");File temporary=File.createTempFile("import-",".part",directory),target=null,coverFile=null;Bitmap cover=null;try{long size=0;try(InputStream input=host.getContentResolver().openInputStream(uri);OutputStream output=new FileOutputStream(temporary)){if(input==null)throw new IOException("Cannot read selected file");byte[] buffer=new byte[16384];int count;while((count=input.read(buffer))!=-1){size+=count;if(size>52428800L||used+size>250000000L)throw new IOException("Book exceeds import storage limits");output.write(buffer,0,count);}}if(size==0)throw new IOException("Selected file is empty");byte[] magic=new byte[5];try(InputStream input=new FileInputStream(temporary)){input.read(magic);}String format;if(magic[0]=='%'&&magic[1]=='P'&&magic[2]=='D'&&magic[3]=='F'&&magic[4]=='-')format="PDF";else if(magic[0]=='P'&&magic[1]=='K'){try(ZipFile zip=new ZipFile(temporary)){ZipEntry mime=zip.getEntry("mimetype");if(mime==null||zip.getEntry("META-INF/container.xml")==null||mime.getSize()>100)throw new IOException("ZIP file is not a supported EPUB");byte[] type;try(InputStream input=zip.getInputStream(mime)){type=BookData.read(input,100);}if(!new String(type,"UTF-8").trim().equals("application/epub+zip"))throw new IOException("ZIP file is not EPUB");}format="EPUB";}else{if(size>8000000L)throw new IOException("Text books must be at most 8 MB");byte[] bytes;try(InputStream input=new FileInputStream(temporary)){bytes=BookData.read(input,8000000);}String text=Charset.forName("UTF-8").newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes)).toString();for(int i=0;i<text.length();i++){char c=text.charAt(i);if(c<32&&c!='\n'&&c!='\r'&&c!='\t'&&c!='\f')throw new IOException("Unsupported binary file; choose PDF, EPUB or UTF-8 text");}format="TXT";}String id=UUID.randomUUID().toString();target=new File(directory,id+"."+format.toLowerCase(java.util.Locale.US));if(!temporary.renameTo(target))throw new IOException("Cannot store imported book");String title=name.lastIndexOf('.')>0?name.substring(0,name.lastIndexOf('.')):name,author="";int pages=0;if(format.equals("PDF")){PdfPages.Page first=PdfPages.render(host,target,0,240,320);cover=first.image;pages=first.count;if(first.title!=null&&!first.title.trim().isEmpty())title=first.title;author=first.author;}else{BookData parsed=BookData.load(target);if(!parsed.title.equals("Book"))title=parsed.title;author=parsed.author;if(parsed.cover!=null){BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(parsed.cover,0,parsed.cover.length,options);options.inSampleSize=1;while(options.outWidth/options.inSampleSize>240||options.outHeight/options.inSampleSize>320)options.inSampleSize*=2;options.inJustDecodeBounds=false;cover=BitmapFactory.decodeByteArray(parsed.cover,0,parsed.cover.length,options);}}if(cover!=null){coverFile=new File(directory,id+".png");try(OutputStream output=new FileOutputStream(coverFile)){if(!cover.compress(Bitmap.CompressFormat.PNG,100,output))throw new IOException("Cannot save book cover");}cover.recycle();cover=null;}JSONObject record=new JSONObject().put("id",id).put("file",target.getName()).put("title",title).put("author",author).put("format",format);if(format.equals("PDF"))record.put("pages",pages);final File stored=target,thumbnail=coverFile;host.ui.post(()->{try{JSONArray index=host.index();if(index.length()>=100)throw new IOException("Bookshelf limit reached");index.put(record);if(!host.prefs.edit().putString("books.index",index.toString()).commit())throw new IOException("Could not save bookshelf index");host.toast("Added to bookshelf / "+record.optString("format"));if(stamp==host.revision){host.shelfPage=0;host.bookshelf();}}catch(Exception error){remove(stored,thumbnail);host.toast("Import failed / "+error.getMessage());}});}catch(Exception error){remove(target,coverFile);throw error;}finally{temporary.delete();if(cover!=null)cover.recycle();}});}
}
